//! Workbook parsing through the JSON, NDJSON and Arrow IPC paths.
//!
//! The input is built in memory and is the same on every run: one sheet of
//! 20,000 rows by 10 columns (200,000 cells) mixing shared strings (a table
//! of 10,000, of which the cells refer to 3,000), numbers, dates, formulas,
//! booleans and inline strings, deflated as a real workbook is. The Arrow and NDJSON entry points take a path, so
//! the generated bytes are written once to a temporary file during setup.

use std::fmt::Write as _;
use std::hint::black_box;
use std::io::{Cursor, Write};
use std::time::Duration;

use criterion::{criterion_group, criterion_main, BatchSize, Criterion, Throughput};
use xlsx_fast_core::arrow::{parse_xlsx_to_arrow_ipc_bytes, ArrowOptions};
use xlsx_fast_core::{parse_xlsx_bytes, parse_xlsx_to_writer, ParseOptions};
use zip::write::SimpleFileOptions;
use zip::{CompressionMethod, ZipWriter};

const ROWS: u32 = 20_000;
const COLS: u32 = 10;
const SHARED_STRINGS: u32 = 10_000;
const NS: &str = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
const REL: &str = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";

const ROOT_RELS: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>"#;

const WORKBOOK_RELS: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>"#;

/// Cell style 1 is the built-in date format 14; style 0 is General.
const STYLES: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cellXfs count="2"><xf numFmtId="0"/><xf numFmtId="14"/></cellXfs></styleSheet>"#;

fn column_letter(col: u32) -> char {
    char::from(b'A' + col as u8)
}

fn sheet_xml() -> String {
    let mut xml =
        format!(r#"<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="{NS}"><sheetData>"#);
    for row in 1..=ROWS {
        write!(xml, r#"<row r="{row}">"#).unwrap();
        for col in 0..COLS {
            let cell = format!("{}{row}", column_letter(col));
            let n = row * COLS + col;
            match col {
                0 | 5 | 8 => write!(
                    xml,
                    r#"<c r="{cell}" t="s"><v>{}</v></c>"#,
                    (n * 7) % SHARED_STRINGS
                ),
                1 | 9 => write!(xml, r#"<c r="{cell}"><v>{}</v></c>"#, n * 3),
                2 => write!(
                    xml,
                    r#"<c r="{cell}" s="1"><v>{}.5</v></c>"#,
                    40_000 + row % 5_000
                ),
                3 => write!(
                    xml,
                    r#"<c r="{cell}"><f>SUM(B{row},J{row})*1.5</f><v>{}.25</v></c>"#,
                    n * 6
                ),
                4 => write!(
                    xml,
                    r#"<c r="{cell}" t="inlineStr"><is><t>inline &amp; text {n}</t></is></c>"#
                ),
                6 => write!(xml, r#"<c r="{cell}"><v>{}.{:03}</v></c>"#, n, n % 1000),
                _ => write!(xml, r#"<c r="{cell}" t="b"><v>{}</v></c>"#, n % 2),
            }
            .unwrap();
        }
        xml.push_str("</row>");
    }
    xml.push_str("</sheetData></worksheet>");
    xml
}

fn shared_strings_xml() -> String {
    let mut xml = format!(r#"<?xml version="1.0" encoding="UTF-8"?><sst xmlns="{NS}">"#);
    for index in 0..SHARED_STRINGS {
        write!(
            xml,
            "<si><t>Customer {index} &amp; Sons, região {}</t></si>",
            index % 97
        )
        .unwrap();
    }
    xml.push_str("</sst>");
    xml
}

/// The generated workbook and the size of its parts before compression.
fn workbook() -> (Vec<u8>, usize) {
    let workbook = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="{NS}" xmlns:r="{REL}"><sheets><sheet name="Data" sheetId="1" r:id="rId1"/></sheets></workbook>"#
    );
    let sheet = sheet_xml();
    let shared = shared_strings_xml();
    let mut zip = ZipWriter::new(Cursor::new(Vec::new()));
    let options = SimpleFileOptions::default().compression_method(CompressionMethod::Deflated);
    let mut inflated = 0;
    for (name, body) in [
        ("_rels/.rels", ROOT_RELS),
        ("xl/workbook.xml", workbook.as_str()),
        ("xl/_rels/workbook.xml.rels", WORKBOOK_RELS),
        ("xl/styles.xml", STYLES),
        ("xl/sharedStrings.xml", shared.as_str()),
        ("xl/worksheets/sheet1.xml", sheet.as_str()),
    ] {
        zip.start_file(name, options).unwrap();
        zip.write_all(body.as_bytes()).unwrap();
        inflated += body.len();
    }
    (zip.finish().unwrap().into_inner(), inflated)
}

fn bench(c: &mut Criterion) {
    let (bytes, inflated) = workbook();
    let options = ParseOptions {
        include_formulas: true,
        ..ParseOptions::default()
    };
    let cells = u64::from(ROWS * COLS);

    // Peak memory is measured outside criterion: set this to write the
    // generated input to a file a one-shot driver can parse.
    if let Some(path) = std::env::var_os("PARSERS_BENCH_DUMP_INPUT") {
        std::fs::write(path, &bytes).unwrap();
    }

    // A package that parses to nothing would look very fast: check it first.
    let parsed = parse_xlsx_bytes(bytes.clone(), options).unwrap();
    assert_eq!(parsed.sheets.len(), 1);
    assert_eq!(parsed.sheets[0].cells.len() as u64, cells);
    assert!(parsed.sheets[0].cells.iter().any(|c| c.formula.is_some()));
    let json = serde_json::to_vec(&parsed).unwrap();
    assert!(json.windows(6).any(|w| w == b"\"date\""));
    drop(parsed);

    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("bench.xlsx");
    std::fs::write(&path, &bytes).unwrap();

    eprintln!(
        "xlsx input: {cells} cells, {} bytes zipped, {inflated} bytes of XML, {} bytes of JSON",
        bytes.len(),
        json.len()
    );

    let mut group = c.benchmark_group("xlsx_200k_cells");
    group
        .throughput(Throughput::Bytes(inflated as u64))
        .sample_size(20)
        .measurement_time(Duration::from_secs(8));
    group.bench_function("json", |b| {
        b.iter_batched(
            || bytes.clone(),
            |bytes| {
                let workbook = parse_xlsx_bytes(bytes, options).unwrap();
                black_box(serde_json::to_vec(&workbook).unwrap())
            },
            BatchSize::LargeInput,
        );
    });
    group.bench_function("parse_only", |b| {
        b.iter_batched(
            || bytes.clone(),
            |bytes| black_box(parse_xlsx_bytes(bytes, options).unwrap()),
            BatchSize::LargeInput,
        );
    });
    group.bench_function("ndjson", |b| {
        b.iter(|| {
            let mut out = Vec::with_capacity(json.len() * 2);
            parse_xlsx_to_writer(&path, &mut out, options).unwrap();
            black_box(out)
        });
    });
    group.bench_function("arrow_ipc", |b| {
        b.iter(|| {
            black_box(
                parse_xlsx_to_arrow_ipc_bytes(&path, options, ArrowOptions::default()).unwrap(),
            )
        });
    });
    group.finish();
}

criterion_group!(benches, bench);
criterion_main!(benches);
